var n=`1148-banana-bread`;var t=`world-1148`;var i=`US`;var r=`northern-america`;var o=8;var s=112;var u={en:`Banana Bread`,ua:`Банановий хліб`};var d={en:`Banana Bread is a dish from United States prepared with banana, chicken egg, all-purpose flour, baking soda. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Банановий хліб, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: банан, куряче яйце, пшеничне борошно універсальне, харчова сода. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Drain the cooked ingredients and pound or mash while warm for about 5 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 5 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:5,i:[[`banana`,4,`pcs`]]},{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:9,i:[[`unsalted-butter`,120,`g`],[`white-granulated-sugar`,155,`g`],[`chicken-egg`,2,`pcs`]]},{en:`Gently fold in the remaining dry or wet ingredients just until homogeneous, without deflating the mixture.`,ua:`Обережно вмішайте решту сухих або рідких складників лише до однорідності, не осаджуючи масу.`,t:[`folding-batter`],m:8,i:[[`all-purpose-flour`,300,`g`],[`baking-soda`,7,`g`],[`plain-yogurt`,110,`g`],[`ground-cinnamon`,4,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 55 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 55 хвилин до готовності.`,t:[`baking`],m:55,i:[]},{en:`Refrigerate the prepared mixture for about 35 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 35 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:35,i:[]}];var h={slug:n,id:t,country:`US`,region:r,servings:8,minutes:112,title:u,text:d,steps:g};export{i as country,h as default,t as id,s as minutes,r as region,o as servings,n as slug,g as steps,d as text,u as title};